import { Redis } from '@upstash/redis';
if (!process.env.VOLTER_WORLD) throw new Error('Run this app through its World.');
const redis = Redis.fromEnv();
const profile = { id: 'profile-1001', name: 'Ada', plan: 'starter' };
const mode = process.argv[2] ?? 'read';
if (mode === 'write') {
  const result = await redis.set('app:profile', profile);
  if (result !== 'OK') throw new Error('The profile write was refused: ' + String(result));
}
const value = await redis.get('app:profile');
if (JSON.stringify(value) !== JSON.stringify(profile)) throw new Error('The retained profile differs from the app write.');
console.log(JSON.stringify({ key: 'app:profile', mode, value }));

